package cn.gov.document.platform.integration.api;import cn.gov.document.platform.integration.domain.AuditLogEntity;import java.time.OffsetDateTime;
public final class AuditDtos{private AuditDtos(){}public record Response(String id,String auditType,String operatorId,String operatorRole,String targetType,String targetId,String action,String detail,String dataLevel,String ipAddress,OffsetDateTime occurredAt){public static Response from(AuditLogEntity e){return new Response(e.getId(),e.getAuditType(),e.getOperatorId(),e.getOperatorRole(),e.getTargetType(),e.getTargetId(),e.getAction(),e.getDetail(),e.getDataLevel(),e.getIpAddress(),e.getOccurredAt());}}}
